"use client"
import { useState, useEffect, useRef } from 'react'

type BookRecord = {
  id: string
  title: string
  size: string
  isbn: string
  author: string
  genre: string
  layoutDesigner: string
  collaboratorArtist: string
  description: string
  coverImageUrl: string
  publication: string
  hasSpotUV: boolean
  hasMatteLamination: boolean
  hasFoilEmboss: boolean
  purchaseLink: string
  createdAt: string
}

const PUBLICATIONS = [
  { value: 'fp', label: 'Fine Print (FP)' },
  { value: 'bh', label: 'Bookhill (BH)' },
  { value: 'nepalaya', label: 'Nepalaya (NP)' },
  { value: 'kitab', label: 'Kitab (KT)' },
  { value: 'sunbarshi', label: 'Sunbarshi (SB)' },
  { value: 'kalam', label: 'Kalam (KL)' },
  { value: 'lipi', label: 'Lipi (LP)' },
  { value: 'indigo', label: 'Indigo (IN)' },
  { value: 'other', label: 'Other' },
]

const empty = {
  title: '', size: '', isbn: '', author: '', genre: '',
  layoutDesigner: '', collaboratorArtist: '', description: '',
  coverImageUrl: '', publication: 'fp',
  hasSpotUV: false, hasMatteLamination: false, hasFoilEmboss: false,
  purchaseLink: '',
}

export default function AdminPage() {
  const [books, setBooks] = useState<BookRecord[]>([])
  const [form, setForm] = useState(empty)
  const [uploading, setUploading] = useState(false)
  const [submitting, setSubmitting] = useState(false)
  const [message, setMessage] = useState<{ type: 'success' | 'error'; text: string } | null>(null)
  const [isAuthenticated, setIsAuthenticated] = useState(false)
  const [emailInput, setEmailInput] = useState('')
  const [passwordInput, setPasswordInput] = useState('')
  const fileRef = useRef<HTMLInputElement>(null)

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault()
    // Hardcoded credentials for now.
    if (emailInput === 'yogalsachin@gmail.com' && passwordInput === 'Sachin@Yogal2026!') {
      setIsAuthenticated(true)
      setMessage(null)
    } else {
      setMessage({ type: 'error', text: 'Incorrect email or password' })
    }
  }

  useEffect(() => {
    fetch('/api/books').then(r => r.json()).then(setBooks).catch(console.error)
  }, [])

  const handleUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (!file) return
    setUploading(true)
    try {
      const fd = new FormData()
      fd.append('file', file)
      const res = await fetch('/api/upload', { method: 'POST', body: fd })
      const data = await res.json()
      if (data.url) {
        setForm(f => ({ ...f, coverImageUrl: data.url }))
        setMessage({ type: 'success', text: 'Image uploaded!' })
      }
    } catch {
      setMessage({ type: 'error', text: 'Image upload failed' })
    } finally {
      setUploading(false)
    }
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!form.title.trim()) {
      setMessage({ type: 'error', text: 'Title is required' })
      return
    }
    setSubmitting(true)
    try {
      const res = await fetch('/api/books', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(form),
      })
      if (res.ok) {
        const newBook = await res.json()
        setBooks(prev => [newBook, ...prev])
        setForm(empty)
        if (fileRef.current) fileRef.current.value = ''
        setMessage({ type: 'success', text: `"${newBook.title}" added successfully!` })
      } else {
        setMessage({ type: 'error', text: 'Failed to add book' })
      }
    } catch {
      setMessage({ type: 'error', text: 'Network error' })
    } finally {
      setSubmitting(false)
    }
  }

  const set = (key: string) => (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) =>
    setForm(f => ({ ...f, [key]: e.target.type === 'checkbox' ? (e.target as HTMLInputElement).checked : e.target.value }))

  /* ── Styles ── */
  const pageStyle: React.CSSProperties = {
    minHeight: '100vh', background: '#0e0c0a', color: '#f4f1ea',
    fontFamily: 'Inter, sans-serif', padding: 'clamp(1.5rem, 5vw, 4rem)',
  }
  const cardStyle: React.CSSProperties = {
    background: 'rgba(255,255,255,0.04)', border: '1px solid rgba(255,255,255,0.08)',
    borderRadius: '12px', padding: 'clamp(1.5rem, 3vw, 2.5rem)',
    maxWidth: 720, margin: '0 auto',
  }
  const inputStyle: React.CSSProperties = {
    width: '100%', padding: '0.75rem 1rem', background: 'rgba(255,255,255,0.06)',
    border: '1px solid rgba(255,255,255,0.12)', borderRadius: '8px',
    color: '#f4f1ea', fontSize: '0.875rem', fontFamily: 'Inter, sans-serif',
    outline: 'none', transition: 'border-color 0.2s',
  }
  const labelStyle: React.CSSProperties = {
    display: 'block', fontSize: '0.7rem', fontWeight: 500,
    letterSpacing: '0.12em', textTransform: 'uppercase',
    color: 'rgba(244,241,234,0.5)', marginBottom: '0.4rem',
  }
  const fieldWrap: React.CSSProperties = { marginBottom: '1.25rem' }
  const btnStyle: React.CSSProperties = {
    width: '100%', padding: '0.875rem', background: '#c9a227',
    color: '#0e0c0a', border: 'none', borderRadius: '8px',
    fontSize: '0.8rem', fontWeight: 600, letterSpacing: '0.1em',
    textTransform: 'uppercase', cursor: 'pointer', transition: 'opacity 0.2s',
  }
  const rowStyle: React.CSSProperties = {
    display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1rem',
  }

  return (
    <div style={pageStyle}>
      {/* Header */}
      <div style={{ maxWidth: 720, margin: '0 auto 2rem', textAlign: 'center' }}>
        <h1 style={{
          fontFamily: "'Fraunces', serif", fontSize: 'clamp(1.75rem, 4vw, 2.5rem)',
          fontWeight: 200, letterSpacing: '-0.03em', marginBottom: '0.5rem',
        }}>
          Book Admin
        </h1>
        <p style={{ fontSize: '0.8rem', color: 'rgba(244,241,234,0.4)', letterSpacing: '0.08em' }}>
          Add new books to the portfolio
        </p>
      </div>

      {/* Message Toast */}
      {message && (
        <div style={{
          maxWidth: 720, margin: '0 auto 1.5rem', padding: '0.75rem 1rem',
          borderRadius: '8px', fontSize: '0.8rem',
          background: message.type === 'success' ? 'rgba(42,157,86,0.15)' : 'rgba(220,53,69,0.15)',
          border: `1px solid ${message.type === 'success' ? 'rgba(42,157,86,0.3)' : 'rgba(220,53,69,0.3)'}`,
          color: message.type === 'success' ? '#2a9d56' : '#dc3545',
          display: 'flex', justifyContent: 'space-between', alignItems: 'center',
        }}>
          {message.text}
          <button onClick={() => setMessage(null)} style={{
            background: 'none', border: 'none', color: 'inherit', cursor: 'pointer', fontSize: '1rem',
          }}>×</button>
        </div>
      )}

      {!isAuthenticated ? (
        <div style={cardStyle}>
          <form onSubmit={handleLogin} style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
            <div style={fieldWrap}>
              <label style={labelStyle}>Admin Email</label>
              <input 
                type="email"
                style={inputStyle} 
                value={emailInput} 
                onChange={(e) => setEmailInput(e.target.value)}
                placeholder="Enter email" 
                onFocus={e => e.currentTarget.style.borderColor = '#c9a227'}
                onBlur={e => e.currentTarget.style.borderColor = 'rgba(255,255,255,0.12)'} 
                autoFocus
              />
            </div>
            <div style={fieldWrap}>
              <label style={labelStyle}>Admin Password</label>
              <input 
                type="password"
                style={inputStyle} 
                value={passwordInput} 
                onChange={(e) => setPasswordInput(e.target.value)}
                placeholder="Enter password" 
                onFocus={e => e.currentTarget.style.borderColor = '#c9a227'}
                onBlur={e => e.currentTarget.style.borderColor = 'rgba(255,255,255,0.12)'} 
              />
            </div>
            <button type="submit" style={btnStyle}>
              Login
            </button>
          </form>
        </div>
      ) : (
        <>
          {/* Form */}
          <div style={cardStyle}>
        <form onSubmit={handleSubmit}>
          <div style={fieldWrap}>
            <label style={labelStyle}>Title *</label>
            <input style={inputStyle} value={form.title} onChange={set('title')}
              placeholder="पियूसी बित्तो" onFocus={e => e.currentTarget.style.borderColor = '#c9a227'}
              onBlur={e => e.currentTarget.style.borderColor = 'rgba(255,255,255,0.12)'} />
          </div>

          <div style={rowStyle}>
            <div style={fieldWrap}>
              <label style={labelStyle}>Author</label>
              <input style={inputStyle} value={form.author} onChange={set('author')}
                placeholder="साउभाका" onFocus={e => e.currentTarget.style.borderColor = '#c9a227'}
                onBlur={e => e.currentTarget.style.borderColor = 'rgba(255,255,255,0.12)'} />
            </div>
            <div style={fieldWrap}>
              <label style={labelStyle}>Genre</label>
              <input style={inputStyle} value={form.genre} onChange={set('genre')}
                placeholder="Fiction (Novel)" onFocus={e => e.currentTarget.style.borderColor = '#c9a227'}
                onBlur={e => e.currentTarget.style.borderColor = 'rgba(255,255,255,0.12)'} />
            </div>
          </div>

          <div style={rowStyle}>
            <div style={fieldWrap}>
              <label style={labelStyle}>Size</label>
              <input style={inputStyle} value={form.size} onChange={set('size')}
                placeholder="5.5 × 8.5 inches" onFocus={e => e.currentTarget.style.borderColor = '#c9a227'}
                onBlur={e => e.currentTarget.style.borderColor = 'rgba(255,255,255,0.12)'} />
            </div>
            <div style={fieldWrap}>
              <label style={labelStyle}>ISBN</label>
              <input style={inputStyle} value={form.isbn} onChange={set('isbn')}
                placeholder="978-9937-928-08-3" onFocus={e => e.currentTarget.style.borderColor = '#c9a227'}
                onBlur={e => e.currentTarget.style.borderColor = 'rgba(255,255,255,0.12)'} />
            </div>
          </div>

          <div style={rowStyle}>
            <div style={fieldWrap}>
              <label style={labelStyle}>Layout Designer</label>
              <input style={inputStyle} value={form.layoutDesigner} onChange={set('layoutDesigner')}
                placeholder="Designer name" onFocus={e => e.currentTarget.style.borderColor = '#c9a227'}
                onBlur={e => e.currentTarget.style.borderColor = 'rgba(255,255,255,0.12)'} />
            </div>
            <div style={fieldWrap}>
              <label style={labelStyle}>Collaborator / Artist</label>
              <input style={inputStyle} value={form.collaboratorArtist} onChange={set('collaboratorArtist')}
                placeholder="Artist name" onFocus={e => e.currentTarget.style.borderColor = '#c9a227'}
                onBlur={e => e.currentTarget.style.borderColor = 'rgba(255,255,255,0.12)'} />
            </div>
          </div>

          <div style={fieldWrap}>
            <label style={labelStyle}>Publication</label>
            <select style={{ ...inputStyle, cursor: 'pointer' }} value={form.publication} onChange={set('publication')}>
              {PUBLICATIONS.map(p => (
                <option key={p.value} value={p.value} style={{ background: '#1a1816', color: '#f4f1ea' }}>
                  {p.label}
                </option>
              ))}
            </select>
          </div>

          <div style={fieldWrap}>
            <label style={labelStyle}>Purchase Link (URL)</label>
            <input style={inputStyle} value={form.purchaseLink} onChange={set('purchaseLink')}
              placeholder="https://example.com/buy" onFocus={e => e.currentTarget.style.borderColor = '#c9a227'}
              onBlur={e => e.currentTarget.style.borderColor = 'rgba(255,255,255,0.12)'} />
          </div>

          <div style={fieldWrap}>
            <label style={labelStyle}>Printing Effects</label>
            <div style={{ display: 'flex', gap: '1.5rem', marginTop: '0.5rem' }}>
              <label style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', fontSize: '0.8rem', cursor: 'pointer' }}>
                <input type="checkbox" checked={form.hasSpotUV} onChange={set('hasSpotUV')} />
                Spot UV
              </label>
              <label style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', fontSize: '0.8rem', cursor: 'pointer' }}>
                <input type="checkbox" checked={form.hasMatteLamination} onChange={set('hasMatteLamination')} />
                Matte Lamination
              </label>
              <label style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', fontSize: '0.8rem', cursor: 'pointer' }}>
                <input type="checkbox" checked={form.hasFoilEmboss} onChange={set('hasFoilEmboss')} />
                Foil Emboss
              </label>
            </div>
          </div>

          <div style={fieldWrap}>
            <label style={labelStyle}>Description</label>
            <textarea style={{ ...inputStyle, minHeight: 100, resize: 'vertical' }}
              value={form.description} onChange={set('description')}
              placeholder="Nepali description..." onFocus={e => e.currentTarget.style.borderColor = '#c9a227'}
              onBlur={e => e.currentTarget.style.borderColor = 'rgba(255,255,255,0.12)'} />
          </div>

          <div style={fieldWrap}>
            <label style={labelStyle}>Cover Image</label>
            <div style={{ display: 'flex', gap: '0.75rem', alignItems: 'center' }}>
              <input ref={fileRef} type="file" accept="image/*" onChange={handleUpload}
                style={{ ...inputStyle, padding: '0.5rem 0.75rem', flex: 1 }} />
              {uploading && <span style={{ fontSize: '0.75rem', color: '#c9a227' }}>Uploading…</span>}
            </div>
            {form.coverImageUrl && (
              <div style={{ marginTop: '0.75rem', display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
                <img src={form.coverImageUrl} alt="Preview" style={{
                  width: 60, height: 80, objectFit: 'cover', borderRadius: '4px',
                  border: '1px solid rgba(255,255,255,0.1)',
                }} />
                <span style={{ fontSize: '0.75rem', color: 'rgba(244,241,234,0.5)' }}>
                  {form.coverImageUrl}
                </span>
              </div>
            )}
            <p style={{ fontSize: '0.65rem', color: 'rgba(244,241,234,0.3)', marginTop: '0.4rem' }}>
              Or type a path manually:
            </p>
            <input style={{ ...inputStyle, marginTop: '0.3rem' }} value={form.coverImageUrl}
              onChange={set('coverImageUrl')} placeholder="/books/book.jpg"
              onFocus={e => e.currentTarget.style.borderColor = '#c9a227'}
              onBlur={e => e.currentTarget.style.borderColor = 'rgba(255,255,255,0.12)'} />
          </div>

          <button type="submit" style={{ ...btnStyle, opacity: submitting ? 0.6 : 1 }} disabled={submitting}>
            {submitting ? 'Adding…' : 'Add Book'}
          </button>
        </form>
      </div>

      {/* Book list */}
      {books.length > 0 && (
        <div style={{ maxWidth: 720, margin: '3rem auto 0' }}>
          <h2 style={{
            fontFamily: "'Fraunces', serif", fontSize: '1.25rem', fontWeight: 200,
            letterSpacing: '-0.02em', marginBottom: '1.25rem', color: 'rgba(244,241,234,0.7)',
          }}>
            Existing Books ({books.length})
          </h2>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '0.75rem' }}>
            {books.map(book => (
              <div key={book.id} style={{
                display: 'flex', gap: '1rem', alignItems: 'center',
                background: 'rgba(255,255,255,0.03)', border: '1px solid rgba(255,255,255,0.06)',
                borderRadius: '8px', padding: '0.75rem 1rem',
              }}>
                {book.coverImageUrl && (
                  <img src={book.coverImageUrl} alt={book.title} style={{
                    width: 40, height: 56, objectFit: 'cover', borderRadius: '3px',
                    border: '1px solid rgba(255,255,255,0.08)',
                  }} />
                )}
                <div style={{ flex: 1, minWidth: 0 }}>
                  <p style={{ fontSize: '0.875rem', fontWeight: 500, margin: 0 }}>{book.title}</p>
                  <p style={{ fontSize: '0.7rem', color: 'rgba(244,241,234,0.4)', margin: '0.15rem 0 0' }}>
                    {book.author && `${book.author} · `}{book.publication} · {book.genre}
                  </p>
                </div>
                <span style={{ fontSize: '0.6rem', color: 'rgba(244,241,234,0.25)', whiteSpace: 'nowrap' }}>
                  {new Date(book.createdAt).toLocaleDateString()}
                </span>
              </div>
            ))}
          </div>
        </div>
      )}
        </>
      )}
    </div>
  )
}
